parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;

const results = items.map(item => {
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini'
        }
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    const detection = JSON.parse(content);

    return {
      json: {
        success: true,
        data: {
          code: detection.code || 'unknown',
          name: detection.name || 'Unknown',
          confidence: detection.confidence || 0,
          script: detection.script || 'unknown',
          is_mixed: detection.is_mixed || false,
          languages: detection.languages || null,
          text_sample: webhookData.body.text.substring(0, 100) + (webhookData.body.text.length > 100 ? '...' : '')
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini'
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse detection response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini'
        }
      }
    };
  }
});

return results;
